def ball(adj, v, k):
    current = {v}
    for _ in range(k):
        expansion = set()
        for u in current:
            expansion |= adj[u]
        current = current | expansion
    return current

def coarse_grain(n, adj, partition):
    node_to_block = {}
    for idx, block in enumerate(partition):
        for node in block:
            node_to_block[node] = idx
    m = len(partition)
    coarse_adj = {i: set() for i in range(m)}
    for u in range(n):
        for v in adj[u]:
            bu, bv = node_to_block[u], node_to_block[v]
            if bu != bv:
                coarse_adj[bu].add(bv)
    return m, coarse_adj

import numpy as np
def laplacian_spectrum(n, adj):
    A = np.zeros((n, n))
    for u in range(n):
        for v in adj[u]:
            A[u, v] = 1.0
    A_sym = (A + A.T) / 2.0
    D = np.diag(A_sym.sum(axis=1))
    L = D - A_sym
    return np.sort(np.linalg.eigvalsh(L))
